import {el,add,button,panel,checkbox} from './render-utils.js';
import {startExam,finalizeExam,remainingMs,gradeExam,examTotals} from './exam-engine.js';
export function examView(ctx){const {root,state,bank,save,render}=ctx;let e=state.exam;root.append(button('← Tổng quan',ctx.home,'quiet back'));
 if(!e){add(root,el('p','BÀI THI TRÊN GIẤY',{class:'eyebrow'}),el('h1','Một giờ.\nBa mươi câu.'),el('p','Chuẩn bị giấy, bút và đánh số từ 1 đến 30. Viết câu trả lời trên giấy; không cần nhập vào điện thoại.'));const c=panel(root);add(c,el('p',`Lấy đều ngẫu nhiên 30 câu trong ${bank.questions.length}/600 câu hiện có. ${bank.questions.length<600?'Bài thi tạm thời vì ngân hàng chưa đủ.':''}`,{class:'warning'}),el('p','Đáp án và lưu ý nguồn chỉ xuất hiện khi nộp bài hoặc hết giờ. Đánh dấu “đã viết” chỉ giúp theo dõi, không tính điểm.'),button('Bắt đầu 60 phút →',()=>{state.exam=startExam(bank.questions);if(save())render();else state.exam=null;},'primary'));return;}
 if(e.finalizedAt===null&&remainingMs(e)===0){finalizeExam(e,'timeout');save();}
 const live=e.finalizedAt===null,q=e.questions[e.index];add(root,el('div',live?'THI TRÊN GIẤY · ĐANG LÀM':'ĐÃ KẾT THÚC · TỰ CHẤM',{class:'eyebrow'}));
 if(live){const top=el('div',null,{class:'row between'});add(top,el('h1',`${e.index+1} / 30`),el('span','',{id:'exam-timer',class:'timer','aria-label':'Thời gian còn lại'}));root.append(top);}else{const t=examTotals(e);add(root,el('h1','Đối chiếu bài viết.'),el('p',`Tự chấm: ${t.correct} đúng · ${t.wrong} sai · ${t.ungraded} chưa chấm.`,{class:'warning'}),el('p',`${e.reason==='timeout'?'Đã hết 60 phút.':'Đã nộp bài sớm.'} Câu chưa chấm không bị tính sai. Đúng ở bài thi không tự cộng thành tích nhớ trễ.`,{class:'muted'}));if(e.reason==='submit'){const spare=Math.max(0,Math.floor((e.endsAt-e.finalizedAt)/60000));root.append(el('small',`Chuyển ${spare} phút thi còn lại sang sửa lỗi / ôn tập trong lịch ngày 3.`));}}
 const c=panel(root);add(c,el('p',`CÂU ${e.index+1} · NGUỒN #${q.sourceId}`,{class:'eyebrow'}),el('h2',q.question,{class:'question'}));
 if(live)c.append(checkbox('Đã viết câu trả lời trên giấy',!!e.checked[q.sourceId],v=>{e.checked[q.sourceId]=v;save();render();}));
 else{const a=el('div',null,{class:'answer'});add(a,el('p','ĐÁP ÁN NGUỒN',{class:'eyebrow'}),el('strong',q.sourceAnswer));if(q.reviewFlags.length)a.append(el('p',`Lưu ý nguồn: ${q.reviewFlags.map(f=>typeof f==='string'?f:JSON.stringify(f)).join(' · ')}`,{class:'warning'}));c.append(a,el('p',`Tự chấm câu này: ${e.grades[q.sourceId]==='correct'?'Đúng':e.grades[q.sourceId]==='wrong'?'Sai':'Chưa chấm'}`));add(c,add(el('div',null,{class:'actions'}),button('Sai',()=>{gradeExam(state,q.sourceId,'wrong');save();render();},'danger'),button('Đúng',()=>{gradeExam(state,q.sourceId,'correct');save();render();},'good')));}
 const nav=el('div',null,{class:'actions'});const prev=button('← Trước',()=>move(-1)),next=button('Tiếp →',()=>move(1));prev.disabled=e.index===0;next.disabled=e.index===29;add(nav,prev,next);c.append(nav);
 function move(delta){e.index+=delta;save();render();}
 const grid=el('div',null,{class:'number-grid'});e.questions.forEach((item,i)=>{const b=button(String(i+1),()=>{e.index=i;save();render();},`${e.index===i?'selected ':''}${e.checked[item.sourceId]?'checked':''}`);b.setAttribute('aria-label',`Câu ${i+1}${e.checked[item.sourceId]?', đã viết':''}`);grid.append(b);});root.append(grid);
 if(live)root.append(button('Nộp bài và xem đáp án',()=>{if(confirm('Kết thúc bài thi ngay và mở đáp án? Bạn không thể quay lại thời gian làm bài.')){finalizeExam(e,'submit');save();render();}},'danger'));
 else add(root,el('p','Các câu tự chấm Sai được đưa vào lượt ôn. Hãy tiếp tục học xen kẽ để kiểm tra rộng hơn.',{class:'muted'}),button('Làm bài ngẫu nhiên mới',()=>{if(confirm('Thay bài thi đang lưu bằng một bài 30 câu mới? Hãy xuất JSON trước nếu muốn giữ bản cũ.')){state.exam=null;save();render();}}));
}
export function updateExamTimer(ctx){const e=ctx.state?.exam;if(!e||e.finalizedAt!==null)return;const ms=remainingMs(e);if(ms===0){finalizeExam(e,'timeout');ctx.save();ctx.render();return;}const timer=document.querySelector('#exam-timer');if(timer){const sec=Math.ceil(ms/1000);timer.textContent=`${Math.floor(sec/60).toString().padStart(2,'0')}:${(sec%60).toString().padStart(2,'0')}`;}}

